            idx1 = a[p]
            if idx1 >= max_len:
                possible = False
                break
            idx2 = a[idx1]
            if idx2 >= max_len:
                possible = False
                break
            idx3 = a[idx2]
            if idx3 >= max_len:
                possible = False
                break
            if idx3 != a[p+1] + 1:
                possible = False
                break
